:root {
  --ink: #0c0b08;
  --panel: rgba(14, 13, 10, 0.72);
  --line: rgba(255, 179, 71, 0.28);
  --amber: #ffb347;
  --amber-hot: #ff8a1f;
  --bone: #f2e9d8;
  --muted: #b7ab94;
  --red: #ff3b30;
  --green: #79d06a;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: #0c0b08;
  color: var(--bone);
  font-family: "Arial Narrow", "Roboto Condensed", "Helvetica Neue", Arial, sans-serif;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  height: 100dvh;
  overflow: hidden;
  background: #14120d;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

/* ============ HUD ============ */
#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  padding: calc(10px + var(--safe-top)) calc(14px + var(--safe-right)) 0 calc(14px + var(--safe-left));
  display: flex;
  flex-direction: column;
  z-index: 5;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  justify-content: space-between;
}

.hud-left {
  width: min(30vw, 280px);
  min-width: 132px;
  filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.6));
}

.health-row {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin-bottom: 4px;
}

.hud-label {
  font-size: 10px;
  letter-spacing: 0.22em;
  color: var(--amber);
  font-weight: 700;
}

.health-value {
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.05em;
  line-height: 1;
}

.health-bar {
  position: relative;
  height: 12px;
  background: rgba(0, 0, 0, 0.68);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 2px;
  overflow: hidden;
  clip-path: polygon(0 0, 100% 0, calc(100% - 6px) 100%, 0 100%);
}

.health-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #4d9b3f, #8ddc6b);
  box-shadow: 0 0 12px rgba(141, 220, 107, 0.45);
  transition: width 0.18s ease, background 0.25s ease;
}

.health-fill.mid {
  background: linear-gradient(90deg, #a7791d, #ffc44d);
  box-shadow: 0 0 12px rgba(255, 196, 77, 0.5);
}

.health-fill.low {
  background: linear-gradient(90deg, #9c1f1f, #ff5148);
  box-shadow: 0 0 14px rgba(255, 80, 72, 0.6);
  animation: pulseLow 0.7s infinite alternate;
}

@keyframes pulseLow {
  from { filter: brightness(0.85); }
  to { filter: brightness(1.35); }
}

.health-notch {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    90deg,
    transparent 0,
    transparent calc(10% - 1px),
    rgba(0, 0, 0, 0.32) calc(10% - 1px),
    rgba(0, 0, 0, 0.32) 10%
  );
  pointer-events: none;
}

.sub-stats {
  margin-top: 5px;
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--muted);
  display: flex;
  gap: 5px;
  align-items: center;
  font-weight: 700;
}

.dot { color: var(--amber); }

.hud-center {
  flex: 1;
  max-width: 430px;
  text-align: center;
  padding-top: 1px;
  filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.7));
}

.sector-label {
  font-size: 10px;
  letter-spacing: 0.34em;
  color: var(--amber);
  font-weight: 700;
}

.objective-text {
  font-size: 13px;
  letter-spacing: 0.06em;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--bone);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.progress-track {
  position: relative;
  height: 4px;
  margin: 7px auto 0;
  width: 78%;
  background: rgba(0, 0, 0, 0.6);
  border-radius: 2px;
  overflow: visible;
}

.progress-fill {
  height: 100%;
  width: 4%;
  background: linear-gradient(90deg, #6f5b2e, var(--amber));
  border-radius: 2px;
  box-shadow: 0 0 8px rgba(255, 179, 71, 0.4);
  transition: width 0.3s ease;
}

.progress-icon {
  position: absolute;
  top: 50%;
  left: 4%;
  transform: translate(-50%, -50%);
  font-size: 9px;
  color: var(--amber);
  text-shadow: 0 0 6px #000;
  transition: left 0.3s ease;
}

.hud-right {
  display: flex;
  gap: 7px;
  pointer-events: auto;
}

.icon-btn {
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255, 179, 71, 0.35);
  background: rgba(12, 11, 8, 0.65);
  color: var(--amber);
  border-radius: 4px;
  font-size: 12px;
  font-weight: 700;
  display: grid;
  place-items: center;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.icon-btn:active { transform: scale(0.94); background: rgba(255, 179, 71, 0.2); }
.icon-btn.muted { color: #6c6355; border-color: rgba(255, 255, 255, 0.12); }

.boss-wrap {
  margin: 12px auto 0;
  width: min(62%, 460px);
  filter: drop-shadow(0 2px 8px rgba(0, 0, 0, 0.75));
  transition: opacity 0.4s;
}

.boss-name {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  letter-spacing: 0.26em;
  color: #ff6b5e;
  font-weight: 700;
  margin-bottom: 4px;
}

.boss-track {
  height: 8px;
  background: rgba(0, 0, 0, 0.72);
  border: 1px solid rgba(255, 80, 64, 0.4);
  clip-path: polygon(4px 0, 100% 0, calc(100% - 4px) 100%, 0 100%);
  overflow: hidden;
}

.boss-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #8e1515, #ff4638);
  box-shadow: 0 0 12px rgba(255, 70, 56, 0.6);
  transition: width 0.15s linear;
}

.ammo-pill {
  position: absolute;
  right: calc(16px + var(--safe-right));
  bottom: calc(232px + var(--safe-bottom));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
  padding: 7px 11px 6px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 5px;
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  filter: drop-shadow(0 2px 8px rgba(0, 0, 0, 0.5));
  min-width: 86px;
}

.weapon-name {
  font-size: 9px;
  letter-spacing: 0.24em;
  color: var(--amber);
  font-weight: 700;
}

.ammo-numbers {
  font-size: 20px;
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: 0.03em;
  font-variant-numeric: tabular-nums;
}

.ammo-numbers b { color: var(--bone); }
.ammo-numbers i { color: var(--muted); font-style: normal; font-size: 14px; margin: 0 1px; }
.ammo-numbers span { color: var(--muted); font-size: 15px; }
.ammo-pill.empty b { color: var(--red); animation: pulseLow 0.5s infinite alternate; }

.toast {
  position: absolute;
  left: 50%;
  bottom: calc(19% + var(--safe-bottom));
  transform: translateX(-50%) translateY(8px);
  padding: 6px 13px;
  background: rgba(12, 11, 8, 0.82);
  border-left: 2px solid var(--amber);
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--bone);
  font-weight: 700;
  opacity: 0;
  transition: opacity 0.25s, transform 0.25s;
  white-space: nowrap;
  text-transform: uppercase;
}

.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

.announce {
  position: absolute;
  top: 22%;
  left: 50%;
  transform: translate(-50%, 0) scale(0.96);
  text-align: center;
  font-size: clamp(24px, 7vw, 54px);
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--bone);
  text-shadow: 0 0 24px rgba(255, 138, 31, 0.7), 0 4px 16px #000;
  opacity: 0;
  pointer-events: none;
  line-height: 1.02;
  width: 92%;
}

.announce small {
  display: block;
  font-size: clamp(9px, 2vw, 13px);
  letter-spacing: 0.42em;
  color: var(--amber);
  margin-top: 9px;
}

.announce.show {
  animation: announceIn 2.1s ease forwards;
}

@keyframes announceIn {
  0% { opacity: 0; transform: translate(-50%, 12px) scale(0.92); letter-spacing: 0.22em; }
  12% { opacity: 1; transform: translate(-50%, 0) scale(1); letter-spacing: 0.12em; }
  78% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -10px) scale(1.01); }
}

.damage-flash {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(255, 30, 20, 0.55) 100%);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.damage-flash.hit { opacity: 1; transition: opacity 0.04s ease; }

.low-health {
  position: absolute;
  inset: 0;
  box-shadow: inset 0 0 90px 18px rgba(190, 15, 10, 0.36);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s;
}

.low-health.on { opacity: 1; animation: lowPulse 1.4s infinite ease-in-out; }

@keyframes lowPulse {
  0%, 100% { opacity: 0.45; }
  50% { opacity: 1; }
}

/* ============ OVERLAY ============ */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  overflow-y: auto;
  padding: calc(22px + var(--safe-top)) 20px calc(24px + var(--safe-bottom));
  background:
    radial-gradient(ellipse at 70% 18%, rgba(255, 124, 32, 0.16), transparent 55%),
    radial-gradient(ellipse at 20% 90%, rgba(120, 70, 20, 0.18), transparent 60%),
    linear-gradient(160deg, rgba(10, 9, 7, 0.86) 0%, rgba(10, 9, 7, 0.94) 55%, rgba(8, 7, 5, 0.98) 100%);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  transition: opacity 0.4s ease, visibility 0.4s;
}

.overlay.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.overlay::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    0deg,
    rgba(255, 255, 255, 0.018) 0px,
    rgba(255, 255, 255, 0.018) 1px,
    transparent 1px,
    transparent 3px
  );
  opacity: 0.45;
}

.overlay-inner {
  position: relative;
  width: min(560px, 100%);
  text-align: center;
  padding: 18px 0 10px;
  animation: overlayIn 0.5s ease both;
}

@keyframes overlayIn {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

.eyebrow {
  font-size: 10px;
  letter-spacing: 0.52em;
  color: var(--amber);
  font-weight: 700;
  margin-bottom: 8px;
  padding-left: 0.52em;
}

.game-title {
  margin: 0;
  font-size: clamp(54px, 15vw, 96px);
  line-height: 0.82;
  letter-spacing: 0.04em;
  font-weight: 700;
  color: var(--bone);
  text-shadow: 0 6px 30px rgba(0, 0, 0, 0.85);
}

.game-title span {
  color: transparent;
  -webkit-text-stroke: 2px var(--amber);
  text-shadow: 0 0 34px rgba(255, 138, 31, 0.4);
}

.tagline {
  margin: 14px auto 0;
  max-width: 420px;
  font-size: 14px;
  line-height: 1.45;
  color: var(--muted);
  letter-spacing: 0.02em;
}

.mission-card {
  margin: 18px auto 0;
  max-width: 470px;
  border-left: 2px solid var(--amber-hot);
  background: linear-gradient(90deg, rgba(255, 138, 31, 0.09), rgba(255, 138, 31, 0.015));
  padding: 11px 15px;
  text-align: left;
}

.mission-card p {
  margin: 0;
  font-size: 12.5px;
  line-height: 1.55;
  color: #d8cdb8;
  letter-spacing: 0.015em;
}

.mission-card strong { color: var(--amber); font-weight: 700; }

.stats-card {
  margin: 18px auto 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  max-width: 440px;
  background: rgba(255, 179, 71, 0.18);
  border: 1px solid rgba(255, 179, 71, 0.2);
}

.stats-card .stat {
  background: rgba(12, 11, 8, 0.9);
  padding: 12px 6px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stats-card .stat b {
  font-size: 23px;
  color: var(--bone);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.stats-card .stat span {
  font-size: 9px;
  letter-spacing: 0.22em;
  color: var(--amber);
  font-weight: 700;
}

.primary-btn {
  margin-top: 22px;
  width: min(320px, 100%);
